#!/usr/bin/env python3
"""Generate pinned Unicode tables and independent Qwen match/split fixtures.

Run with tokenizers==0.22.2. No network access is performed.
"""
import gzip
import hashlib
import itertools
import json
from pathlib import Path
import random
import tokenizers
from tokenizers import Regex, pre_tokenizers as pt

ROOT = Path(__file__).resolve().parents[2]
PATTERN_ID = '1ff7f41064896984db5d1bb6ff64fa4bc29007d08c1b439e505b7392777a319e'

def matcher(pattern, behavior='removed', invert=True):
    return pt.Split(Regex(pattern), behavior, invert=invert)

def main():
    assert tokenizers.__version__ == '0.22.2'
    manifest_path = ROOT/'testdata/qwen/manifest.json'
    pinned = json.loads(manifest_path.read_text())
    pattern = pinned['pattern']
    assert hashlib.sha256(pattern.encode()).hexdigest() == PATTERN_ID
    # Enumerate every Unicode scalar. Python offsets index scalars, not UTF-8 bytes.
    scalars = ''.join(chr(c) for c in range(0x110000) if not 0xD800 <= c <= 0xDFFF)
    tables = {}
    for name, expr in [('letter', r'\p{L}+'), ('number', r'\p{N}+'), ('space', r'\s+')]:
        ranges = []
        for piece, (a,b) in matcher(expr).pre_tokenize_str(scalars):
            assert piece == scalars[a:b]
            lo, hi = ord(piece[0]), ord(piece[-1])
            assert hi-lo+1 == b-a  # No class run crosses the omitted surrogates.
            ranges.append((lo,hi))
        tables[name] = ranges
    # Pin every scalar alternative that can case-fold to an ASCII contraction
    # letter, rather than borrowing Go's potentially different Unicode tables.
    folds = {}
    for char in 'stdmrelv':
        folds[char] = [ord(piece) for piece, _ in matcher('(?i:'+char+')').pre_tokenize_str(scalars)]
        assert all(len(piece)==1 for piece,_ in matcher('(?i:'+char+')').pre_tokenize_str(scalars))
    # No non-ASCII scalar may stand in for an entire two-letter contraction.
    for pair in ['re','ve','ll']:
        assert all(len(piece)==2 for piece,_ in matcher('(?i:'+pair+')').pre_tokenize_str(scalars))
    lines = ['// Code generated by testdata/qwen/generate.py; DO NOT EDIT.',
             '// Unicode membership pinned to tokenizers 0.22.2 native oracle.',
             'package scan', '']
    for name, ranges in tables.items():
        lines += ['var '+name+'Ranges = [...]runeRange{']
        lines += ['{0x%X, 0x%X},' % pair for pair in ranges]
        lines += ['}', '']
    lines += ['func foldContraction(r rune) rune {', 'switch r {']
    for char, values in folds.items():
        lines += ['case '+', '.join('0x%X'%c for c in values)+':', "return '%s'"%char]
    lines += ['}', 'return r', '}']
    table = ROOT/'internal/scan/unicode_tables.go'
    table.write_text('\n'.join(lines)+'\n')
    import subprocess
    subprocess.run(['gofmt','-w',str(table)],check=True)

    matches = matcher(pattern)
    split = matcher(pattern,'isolated',False)
    cases = set(['', "we're I'LL 'ſ 'RE 'Ve 'Ll", "fooBar HTTPServer 中ABC", 'a\u0301b',
                 '\r\n\tA', '\u2003\u2003X', '\u2028\u2029A', '１２²Ⅳ1',
                 '  \nX  \nY  ', "!!'s", '\x00\x1c\x1d\x1e\x1fA',
                 'a'*8193, ' '*8193+'X', '\u2003'*4097+'X',
                 (' \r\n\t'*2049)+'X', '😀'*4097])
    alphabet = ['a',"'",'s','ſ',' ','\r','\n','\t','中','\u0301','1','²','_','😀']
    for n in range(1,4):
        cases.update(''.join(chars) for chars in itertools.product(alphabet, repeat=n))
    for ranges in tables.values():
        for lo,hi in ranges:
            for cp in [lo-1,lo,hi,hi+1]:
                if 0<=cp<0x110000 and not 0xD800<=cp<=0xDFFF:
                    c=chr(cp)
                    cases.add('a'+c+'b '+c+'1'+c+'\r\n')
    rng=random.Random(20260909)
    for _ in range(2000):
        chars=[]
        for _ in range(rng.randrange(1,80)):
            cp=rng.randrange(0x110000)
            chars.append(rng.choice(alphabet) if rng.random()<0.7 or 0xD800<=cp<=0xDFFF else chr(cp))
        cases.add(''.join(chars))
    def spans(pre, text):
        offsets=[0]
        for c in text: offsets.append(offsets[-1]+len(c.encode()))
        out=[]
        for piece,(a,b) in pre.pre_tokenize_str(text):
            assert piece==text[a:b]
            out.append({'Start':offsets[a],'End':offsets[b]})
        return out
    out=ROOT/'testdata/qwen/cases.jsonl.gz'
    with out.open('wb') as raw, gzip.GzipFile(filename='',mode='wb',fileobj=raw,mtime=0) as f:
        for text in sorted(cases):
            line=json.dumps({'input':text,'matches':spans(matches,text),'split':spans(split,text)},ensure_ascii=True,separators=(',',':'))+'\n'
            f.write(line.encode())
    native=Path(tokenizers.__file__).parent/'tokenizers.abi3.so'
    source=pinned['source']
    manifest={'pattern':pattern,'pattern_sha256':PATTERN_ID,'source':source,
              'oracle_version':tokenizers.__version__, 'oracle_native_sha256':hashlib.sha256(native.read_bytes()).hexdigest(),
              'unicode_profile':'Membership of L, N, s and contraction folds from all Unicode scalars in the pinned native oracle; independent of Go unicode.Version.',
              'case_count':len(cases),'cases_sha256':hashlib.sha256(out.read_bytes()).hexdigest(),
              'tables_sha256':hashlib.sha256(table.read_bytes()).hexdigest(),
              'generator_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
              'matches_settings':{'behavior':'Removed','invert':True},
              'split_settings':{'behavior':'Isolated','invert':False}}
    (ROOT/'testdata/qwen/manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
    print('Generated',len(cases),'oracle cases; range counts:',{k:len(v) for k,v in tables.items()})

if __name__=='__main__': main()
